import{_ as p,a0 as o,w as r,s as d,ao as t,I as l,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在无响应的 Linux 系统中杀掉内存消耗最大的进程 | LCTT x X-CMD","titleTemplate":false,"description":"如何在无响应的 Linux 系统中杀掉内存消耗最大的进程 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在无响应的 Linux 系统中杀掉内存消耗最大的进程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在无响应的 Linux 系统中杀掉内存消耗最大的进程 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20171121 How To Kill The Largest Process In An Unresponsive Linux System","title":"如何在无响应的 Linux 系统中杀掉内存消耗最大的进程","tag":"201805","desc":""},"relativePath":"201805/20171121 How To Kill The Largest Process In An Unresponsive Linux System.md","filePath":"[post].md"}'),h={name:"201805/20171121 How To Kill The Largest Process In An Unresponsive Linux System.md"};function g(u,s,k,m,c,b){const e=o("Link");return r(),d("div",null,[s[22]||(s[22]=t(`<h1 id="如何在无响应的-linux-系统中杀掉内存消耗最大的进程" tabindex="-1">如何在无响应的 Linux 系统中杀掉内存消耗最大的进程 <a class="header-anchor" href="#如何在无响应的-linux-系统中杀掉内存消耗最大的进程" aria-label="Permalink to “如何在无响应的 Linux 系统中杀掉内存消耗最大的进程”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/11/Kill-The-Largest-Process-720x340.png" alt=""></p><p>作为一名博客作者，我收藏了很多博客、网站和论坛用来寻找 Linux 和 Unix 相关的内容。有时候，我在浏览器中开启了非常多的标签页，导致操作系统会无响应好几分钟。我不能移动我的鼠标，也不能杀掉一个进程或关闭任何开启的标签页。在这种情况下，我别无选择，只能强制重启系统。当然我也用了 <strong>OneTab</strong> （LCTT 译注：OneTab 是一个 Chrome 的 Extension，可以将标签页转化成一个列表保存。）和 <strong>Greate Suspender</strong> （LCTT 译注：Great Suspender 是一个 Chrome 的 Extension， 可以自动冻结标签页）这样浏览器拓展，但它们在这里也起不到太大的作用。 我经常耗尽我的内存。而这就是 <strong>Early OOM</strong> 起作用的时候了。在情况严重时，它会杀掉一个未响应系统中的内存消耗最大的进程。Early OOM 每秒会检测可用内存和空余交换区 10 次，一旦两者都低于 10%，它就会把最大的进程杀死。</p><h3 id="为什么用-early-oom-为什么不用系统内置的-oom-killer" tabindex="-1">为什么用 Early OOM？为什么不用系统内置的 OOM killer？ <a class="header-anchor" href="#为什么用-early-oom-为什么不用系统内置的-oom-killer" aria-label="Permalink to “为什么用 Early OOM？为什么不用系统内置的 OOM killer？”">​</a></h3><p>在继续讨论下去之前，我想先简短的介绍下 OOM killer，也就是 <strong>O</strong>ut <strong>O</strong>f <strong>M</strong>emory killer。OOM killer 是一个由内核在可用内存非常低的时候使用的进程。它的主要任务是不断的杀死进程，直到释放出足够的内存，使内核正在运行的其它进程能顺利运行。OOM killer 会找到系统中最不重要并且能释放出最多内存的进程，然后杀掉他们。在 <code>/proc</code> 目录下的 <code>pid</code> 目录中，我们可以看到每个进程的 <code>oom_score</code>。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/10299/oom_score</span></span>
<span class="line"><span>1</span></span></code></pre></div><p>一个进程的 <code>oom_score</code> 的值越高，这个进程越有可能在系统内存耗尽的时候被 OOM killer 杀死。</p><p>Early OOM 的开发者表示，相对于内置的 OOM killer，Early OOM 有一个很大的优点。就像我之前说的那样，OOM killer 会杀掉 <code>oom_score</code> 最高的进程，而这也导致 Chrome 浏览器总是会成为第一个被杀死的进程。为了避免这种情况发生，Early OOM 使用 <code>/proc/*/status</code> 而不是 <code>echo f &gt; /proc/sysrq-trigger</code>（LCTT 译注：这条命令会调用 OOM killer 杀死进程）。开发者还表示，手动触发 OOM killer 在最新版本的 Linux 内核中很可能不会起作用。</p><h3 id="安装-early-oom" tabindex="-1">安装 Early OOM <a class="header-anchor" href="#安装-early-oom" aria-label="Permalink to “安装 Early OOM”">​</a></h3><p>Early OOM 在 AUR（Arch User Repository）中可以找到，所以你可以在 Arch 和它的衍生版本中使用任何 AUR 工具安装它。</p>`,11)),l("p",null,[s[1]||(s[1]=a("使用 ",-1)),n(e,{href:"https://www.ostechnix.com/install-pacaur-arch-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("Pacaur",-1)])]),_:1}),s[2]||(s[2]=a("：",-1))]),s[23]||(s[23]=t('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacaur -S earlyoom</span></span></code></pre></div>',1)),l("p",null,[s[4]||(s[4]=a("使用 ",-1)),n(e,{href:"https://www.ostechnix.com/install-packer-arch-linux-2/"},{default:i(()=>[...s[3]||(s[3]=[a("Packer",-1)])]),_:1}),s[5]||(s[5]=a("：",-1))]),s[24]||(s[24]=t('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>packer -S earlyoom</span></span></code></pre></div>',1)),l("p",null,[s[7]||(s[7]=a("使用 ",-1)),n(e,{href:"https://www.ostechnix.com/install-yaourt-arch-linux/"},{default:i(()=>[...s[6]||(s[6]=[a("Yaourt",-1)])]),_:1}),s[8]||(s[8]=a("：",-1))]),s[25]||(s[25]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yaourt -S earlyoom</span></span></code></pre></div><p>启用并启动 Early OOM 守护进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable earlyoom</span></span>
<span class="line"><span>sudo systemctl start earlyoom</span></span></code></pre></div><p>在其它的 Linux 发行版中，可以按如下方法编译安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/rfjakob/earlyoom.git</span></span>
<span class="line"><span>cd earlyoom</span></span>
<span class="line"><span>make</span></span>
<span class="line"><span>sudo make install</span></span></code></pre></div><h3 id="early-oom-杀掉无响应-linux-系统中的最大的进程" tabindex="-1">Early OOM - 杀掉无响应 Linux 系统中的最大的进程 <a class="header-anchor" href="#early-oom-杀掉无响应-linux-系统中的最大的进程" aria-label="Permalink to “Early OOM - 杀掉无响应 Linux 系统中的最大的进程”">​</a></h3><p>运行如下命令启动 Early OOM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom</span></span></code></pre></div><p>如果是通过编译源代码安装的， 运行如下命令启动 Early OOM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./earlyoom</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom 0.12</span></span>
<span class="line"><span>mem total: 3863 MiB, min: 386 MiB (10 %)</span></span>
<span class="line"><span>swap total: 2047 MiB, min: 204 MiB (10 %)</span></span>
<span class="line"><span>mem avail: 1770 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1772 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1772 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1771 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1773 MiB (45 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>mem avail: 1784 MiB (46 %), swap free: 2047 MiB (99 %)</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>就像你在上面的输出中可以看到的，Early OOM 将会显示你有多少内存和交换区，以及有多少可用的内存和交换区。记住它会一直保持运行，直到你按下 <code>CTRL+C</code>。</p><p>如果可用的内存和交换区大小都低于 10%，Early OOM 将会自动杀死最大的进程，直到系统有足够的内存可以流畅的运行。你也可以根据你的需求配置最小百分比值。</p><p>设置最小的可用内存百分比，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom -m &lt;PERCENT_HERE&gt;</span></span></code></pre></div><p>设置最小可用交换区百分比, 运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>earlyoom -s &lt;PERCENT_HERE&gt;</span></span></code></pre></div><p>在帮助部分，可以看到更多详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ earlyoom -h</span></span>
<span class="line"><span>earlyoom 0.12</span></span>
<span class="line"><span>Usage: earlyoom [OPTION]...</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -m PERCENT set available memory minimum to PERCENT of total (default 10 %)</span></span>
<span class="line"><span> -s PERCENT set free swap minimum to PERCENT of total (default 10 %)</span></span>
<span class="line"><span> -M SIZE set available memory minimum to SIZE KiB</span></span>
<span class="line"><span> -S SIZE set free swap minimum to SIZE KiB</span></span>
<span class="line"><span> -k use kernel oom killer instead of own user-space implementation</span></span>
<span class="line"><span> -i user-space oom killer should ignore positive oom_score_adj values</span></span>
<span class="line"><span> -d enable debugging messages</span></span>
<span class="line"><span> -v print version information and exit</span></span>
<span class="line"><span> -r INTERVAL memory report interval in seconds (default 1), set to 0 to</span></span>
<span class="line"><span> disable completely</span></span>
<span class="line"><span> -p set niceness of earlyoom to -20 and oom_score_adj to -1000</span></span>
<span class="line"><span> -h this help text</span></span></code></pre></div><p>现在，你再也不用担心内存消耗最高的进程了。希望这能给你帮助。更多的好内容将会到来，敬请期待。</p><p>谢谢！</p><hr>`,23)),l("p",null,[s[10]||(s[10]=a("via: ",-1)),n(e,{href:"https://www.ostechnix.com/kill-largest-process-unresponsive-linux-system/"},{default:i(()=>[...s[9]||(s[9]=[a("https://www.ostechnix.com/kill-largest-process-unresponsive-linux-system/",-1)])]),_:1})]),l("p",null,[s[14]||(s[14]=a("作者：",-1)),n(e,{href:"https://www.ostechnix.com"},{default:i(()=>[...s[11]||(s[11]=[a("Aditya Goturu",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),n(e,{href:"https://github.com/cizezsy"},{default:i(()=>[...s[12]||(s[12]=[a("cizezsy",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[19]||(s[19]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}const T=p(h,[["render",g]]);export{x as __pageData,T as default};
